package org.skhuconnect.notice.entity; import jakarta.persistence.*; import org.skhuconnect.admin.entity.Admin; import org.skhuconnect.global.entity.BaseEntity; import java.time.LocalDateTime; import java.util.Objects; @Entity @Table(name="notices") public class Notice extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,length=100) String title; @Column(nullable=false,length=5000,columnDefinition="TEXT") String content; @Enumerated(EnumType.STRING) @Column(nullable=false) NoticeStatus status; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="created_by_admin_id",nullable=false) Admin createdBy; LocalDateTime publishedAt; protected Notice(){} private Notice(Admin a,String t,String c){createdBy=a;title=req(t,100);content=req(c,5000);status=NoticeStatus.DRAFT;} public static Notice create(Admin a,String t,String c){return new Notice(a,t,c);} public void update(String t,String c){title=req(t,100);content=req(c,5000);} public boolean publish(){boolean first=status==NoticeStatus.DRAFT;status=NoticeStatus.PUBLISHED;if(publishedAt==null)publishedAt=LocalDateTime.now();return first;} public void hide(){status=NoticeStatus.HIDDEN;} public Long getId(){return id;} public String getTitle(){return title;} public String getContent(){return content;} public NoticeStatus getStatus(){return status;} public Admin getCreatedBy(){return createdBy;} public LocalDateTime getPublishedAt(){return publishedAt;} static String req(String v,int m){if(v==null||v.isBlank()||v.length()>m)throw new IllegalArgumentException();return v;} }